import { createMiddleware } from '@tanstack/react-start'

function getSupabaseEnv() {
  const viteEnv = import.meta.env as Record<string, string | undefined>
  const nodeEnv = typeof process !== 'undefined' ? process.env : undefined

  return {
    url: viteEnv['VITE_SUPABASE_URL'] || nodeEnv?.['SUPABASE_URL'],
    publishableKey:
      viteEnv['VITE_SUPABASE_PUBLISHABLE_KEY'] || nodeEnv?.['SUPABASE_PUBLISHABLE_KEY'],
  }
}

function shouldLoadAuthClient(supabaseUrl: string) {
  if (typeof window === 'undefined') return false

  // Lovable's framed preview can broker an auth session from the editor even
  // before a localStorage copy exists, so keep the normal auth discovery path
  // there. Published storefront visitors do not need the ~300 KB Supabase SDK
  // parsed on every anonymous page load.
  const previewZones = [
    'lovableproject.com',
    'lovableproject-dev.com',
    'lovable.app',
    'gpt-eng.com',
    'gptengineer.run',
  ]
  const host = window.location.hostname
  const onPreviewZone = previewZones.some((zone) => host === zone || host.endsWith(`.${zone}`))
  if (onPreviewZone && window.parent && window.parent !== window) return true

  try {
    const projectRef = new URL(supabaseUrl).hostname.split('.')[0]
    if (!projectRef) return true
    return window.localStorage.getItem(`sb-${projectRef}-auth-token`) !== null
  } catch {
    // If the URL is unusual, preserve the previous behavior rather than risk
    // suppressing authentication for a legitimate signed-in user.
    return true
  }
}

// Must be registered as a global `functionMiddleware` in `src/start.ts`; otherwise
// authenticated browser sessions cannot attach their bearer token to serverFn RPCs.
//
// Keep the Supabase browser SDK out of the critical storefront bundle. Anonymous
// shoppers have no session to attach, while authenticated users dynamically load
// the exact same generated client on the first server function that needs it.
export const attachSupabaseAuth = createMiddleware({ type: 'function' }).client(
  async ({ next }) => {
    const { url, publishableKey } = getSupabaseEnv()
    if (!url || !publishableKey || !shouldLoadAuthClient(url)) {
      return next({ headers: {} })
    }

    try {
      const { supabase } = await import('./client')
      const { data } = await supabase.auth.getSession()
      const token = data.session?.access_token
      return next({
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
    } catch (error) {
      console.warn('[Supabase] Unable to attach auth session; continuing without auth header.', error)
      return next({ headers: {} })
    }
  },
)
